WHERE FIND_IN_SET(p.projectType,:projectTypes) AND (:projectIds='' OR FIND_IN_SET(p.projectId,:projectIds))
 AND (:alreadyMappedProjectIds='' OR NOT FIND_IN_SET(p.projectId,:alreadyMappedProjectIds))
 AND (p.compId IS NULL OR p.column001 IS NULL OR FIND_IN_SET(CONCAT(c.compCode,':',CASE WHEN p.column001 REGEXP '^31120[2-9]$|^311210$' THEN CONCAT('1621',SUBSTRING(p.column001,5)) ELSE p.column001 END),:authorizedOrganizationKeys))
 AND p.projectName IS NOT NULL
