WHERE (g.id IS NULL OR FIND_IN_SET(g.projectType,:projectTypes))
  AND (:projectIds='' OR FIND_IN_SET(p.projectId,:projectIds))
 AND FIND_IN_SET(CONCAT(c.id,':',COALESCE(m.id,0)),:readyOriginalKeys)
;

